const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('vi-VN')+' đ';
const menu=[['⌂','Trang chủ','home'],['⚑','Tạo đơn','create'],['▦','Bảng tính 3 cấp','sheet3'],['▦','Bảng tính 2 cấp','sheet2'],['▣','Đơn hàng','orders'],['◧','Đối soát','reconcile'],['▧','Thống kê','stats'],['?','Yêu cầu','requests'],['▣','Ứng COD','cod'],['☷','Quản lý','manage'],['▦','Tiện ích','utilities'],['⚙','Cài đặt','settings'],['◎','Giới thiệu khách','referrals'],['⋯','Xem thêm','more']];
let orders=[{id:'BDHS983262LM.826883962',name:'Lê Phước Thắng',phone:'033***429',address:'99/1 Hàm Nghi, Phường Bình Định, Thị xã An Nhơn, Tỉnh Bình Định',product:'Mỹ phẩm',weight:750,value:200000,cod:200000,note:'Khách không nhận vui lòng thu 30k phí giao hàng. Cảm ơn!',status:'Chờ Lấy Hàng'}],tickets=[],tab='Tất cả',filtered=null,productMode='manual',sheetRows=[],pickup='25 Hồ Mễ Trì, Phường Mễ Trì, Quận Nam Từ Liêm, Thành phố Hà Nội';
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function field(label,name,placeholder='',value='',type='text',required=false){return `<label class="field"><span>${label}${required?' <b class="required">*</b>':''}</span><input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0"':''}></label>`}
function select(label,name,options,required=false){return `<label class="field"><span>${label}${required?' <b class="required">*</b>':''}</span><select name="${name}" ${required?'required':''}><option value="">${label}</option>${options.map(x=>`<option>${x}</option>`).join('')}</select></label>`}
function card(title,symbol,body){return `<section class="card"><div class="card-title"><span class="card-symbol">${symbol}</span><h3>${title}</h3></div><div class="body">${body}</div></section>`}
function radio(name,label,value,checked=false){return `<label class="choice"><input type="radio" name="${name}" value="${value}" ${checked?'checked':''}>${label}</label>`}
function check(label,name,checked=false){return `<label class="choice"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`}
function pickupBlock(){return `<div class="pickup"><span class="pin">●</span><div><strong>Địa chỉ lấy hàng</strong><br>${esc(pickup)}<br><b>Raspberry Pi VN - 092****688 <span style="color:#2d83ff">◉</span></b></div><button type="button" data-pickup>Thay đổi</button></div>`}
function footer(){return '<footer>2026 © <span class="red">SuperPlatform</span></footer>'}
function render(){const route=location.hash.slice(1)||'create';$('#nav').innerHTML=menu.map(([i,t,r])=>`<a href="#${r}" class="${route===r?'active':''}" title="${t}"><span class="nav-icon">${i}</span><span>${t}</span></a>`).join('');if(route==='create')renderCreate();else if(route==='orders')renderOrders();else if(route.startsWith('sheet'))renderSheet(route);else renderOther(route);bindCommon();window.scrollTo(0,0)}
function renderCreate(){ $('#main').innerHTML=`<h1>Tạo đơn hàng <button class="badge-blue" data-help aria-label="Hướng dẫn tạo đơn">▣</button></h1><form id="create-form"><div class="create-layout"><div><section class="card">${pickupBlock()}<div class="card-title"><span class="card-symbol">♟</span><h3>Thông tin người nhận</h3></div><div class="body"><label class="field"><span>Điền nhanh thông tin <span class="red">(Không bắt buộc)</span></span><textarea id="quick" class="quick" placeholder="✦  Dán thông tin đơn như Tên người nhận, Số điện thoại, Địa chỉ chi tiết, Tên sản phẩm => Hệ thống tự tách và điền vào các ô tương ứng. Ví dụ:&#10;Thảo Lê 0987686868&#10;32 Thân Nhân Trung Phường 13, Q. Tân Bình, TPHCM&#10;2 áo sơ mi kiểu"></textarea></label><p class="hint">Để tính năng hoạt động tốt nhất, vui lòng dán (Ctrl/⌘ + V) thông tin vào ô trước khi thao tác chỉnh sửa.</p><div class="grid2">${field('Số điện thoại','phone','☎  Số điện thoại','','tel',true)}${field('Tên người nhận','name','♟  Tên người nhận','','text',true)}</div><div class="switches"><label><input type="checkbox" name="convert">Tự chuyển 2/3 cấp ⓘ</label><label><input type="checkbox" id="new-address">Địa chỉ mới ⓘ</label></div>${field('Địa chỉ chi tiết','address','●  Địa chỉ chi tiết','','text',true)}${select('Khu vực','region',['Hà Nội · Nam Từ Liêm · Mễ Trì','TP. Hồ Chí Minh · Tân Bình · Phường 13','Bình Định · An Nhơn · Bình Định','Đà Nẵng · Hải Châu · Hòa Cường Bắc'],true)}</div></section>${card('Chi tiết hàng gửi','◆',`<div class="radios">${radio('productMode','Nhập liệu thủ công','manual',true)}${radio('productMode','Chọn từ danh sách','list')}</div><div id="catalog" hidden><input class="control" id="product-search" placeholder="⌕  Chọn sản phẩm"><div class="product-table"><table><thead><tr><th>STT</th><th>Mã Sản Phẩm</th><th>Tên Sản Phẩm</th><th>Giá</th><th>Số Lượng</th></tr></thead><tbody id="products"></tbody></table><div class="empty" id="empty-product"><div class="empty-icon">⌕</div>Chưa có sản phẩm</div></div></div><div class="grid2">${field('Tên sản phẩm','product','◆  Tên sản phẩm','Mỹ phẩm','text',true)}${field('Khối lượng (gr)','weight','','750','number',true)}${field('Giá trị','value','▣  Giá trị','','number',true)}${field('Thu hộ','cod','◉  Thu hộ','','number',true)}</div><div class="section-label">Kích thước <span class="red">(Không bắt buộc)</span><span style="float:right">Khối lượng quy đổi: <b id="volumetric">0 gr</b></span></div><div class="grid3">${field('Chiều dài (cm)','length','','0','number')}${field('Chiều rộng (cm)','width','','0','number')}${field('Chiều cao (cm)','height','','0','number')}</div><div class="section-label">Xem/thử hàng <span class="red">*</span></div><div class="stack">${radio('inspection','Cho Xem Hàng Nhưng Không Cho Thử','view',true)}${radio('inspection','Cho Thử Hàng','try')}${radio('inspection','Không Cho Xem Hàng','none')}</div><div class="grid2">${field('Mã đơn riêng ⓘ','privateId','▥  Mã đơn riêng')}<div style="padding-top:24px">${check('Đổi / Lấy hàng về ⓘ','return')}</div></div><label class="field"><span>Ghi chú khi giao</span><textarea name="note" rows="3" maxlength="120">Khách không nhận vui lòng thu 30k phí giao hàng. Cảm ơn!</textarea></label><p class="hint" style="text-align:right" id="note-count">56 / 120 ký tự</p><div class="section-label">Ảnh hàng hóa <span class="red">(Không bắt buộc)</span></div><label class="upload" title="Tải ảnh hàng hóa"><span>▣</span><input type="file" accept="image/*" id="upload"></label>`)}</div><div class="summary">${card('Người trả phí <span class="red">*</span>','▣',`<div class="radios" style="margin:0">${radio('payer','Người gửi','sender',true)}${radio('payer','Người nhận ⓘ','recipient')}</div>`)}${card('Dịch vụ thêm','⚙',check('Đổi / Lấy hàng về ⓘ','returnService'))}${card('Cước phí','◉',`<div class="fee-row"><span>Giá trị hàng hóa ⓘ</span><b id="fee-value">0 đ</b></div><div class="fee-row"><span>Khối lượng tính cước ⓘ</span><b id="fee-weight">750 gr</b></div><div class="fee-row total"><span>Phí giao hàng (Người gửi trả)</span><b>0 đ</b></div>${['Phí bảo hiểm','Phí hàng đổi','Phí thu hộ'].map(t=>`<div class="fee-row"><span>${t}</span><b>0 đ</b></div>`).join('')}<div class="fee-row total"><span>Tổng phí vận chuyển ⓘ</span><b class="green">0 đ</b></div><div class="fee-row"><span>Tiền thu hộ</span><b id="fee-cod">0 đ</b></div><div class="fee-row"><strong>Tiền thu người nhận ⓘ</strong><b class="red" id="fee-total">0 đ</b></div>`)}${check('Tôi đã đọc và đồng ý với Điều khoản & quy định','terms',true)}<button class="btn primary wide" id="submit-order" disabled>Tạo đơn</button></div></div></form>${footer()}`;
 const f=$('#create-form');f.addEventListener('input',()=>{const d=Object.fromEntries(new FormData(f));$('#fee-value').textContent=money(d.value);$('#fee-cod').textContent=$('#fee-total').textContent=money(d.cod);let v=Math.ceil(d.length*d.width*d.height/5);$('#volumetric').textContent=v+' gr';$('#fee-weight').textContent=Math.max(v,Number(d.weight||0))+' gr';$('#note-count').textContent=d.note.length+' / 120 ký tự';$('#submit-order').disabled=!(d.name&&d.phone&&d.address&&d.region&&d.product&&Number(d.weight)>0&&d.value!==''&&d.cod!==''&&d.terms)});f.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!/^0\d{9}$/.test(d.phone)){toast('Vui lòng nhập số điện thoại gồm 10 chữ số, bắt đầu bằng 0.');return}orders.unshift({...d,id:'SP'+Date.now(),address:d.address+', '+d.region,status:'Chờ Lấy Hàng'});filtered=null;location.hash='orders';toast('Đã tạo đơn mẫu. Chưa gửi sang hệ thống vận chuyển.')});$$('[name=productMode]').forEach(x=>x.onchange=()=>{$('#catalog').hidden=x.value!=='list';productMode=x.value});$('#product-search').oninput=e=>{const q=e.target.value;$('#empty-product').hidden=!!q;$('#products').innerHTML=q?`<tr><td>1</td><td>SP001</td><td><button type="button" class="btn" id="choose-product">Mỹ phẩm</button></td><td>200.000 đ</td><td>1</td></tr>`:'';if(q)$('#choose-product').onclick=()=>{f.elements.product.value='Mỹ phẩm';f.elements.value.value=200000;f.elements.cod.value=200000;f.dispatchEvent(new Event('input'));toast('Đã chọn sản phẩm mẫu Mỹ phẩm')}};$('#upload').onchange=e=>{const file=e.target.files[0];if(file){const img=document.createElement('img');img.alt='Ảnh hàng hóa';img.src=URL.createObjectURL(file);$('.upload span').replaceChildren(img)}};$('#quick').addEventListener('change',e=>{const lines=e.target.value.trim().split('\n');const phone=e.target.value.match(/0\d{9}/);if(phone)f.elements.phone.value=phone[0];if(lines[0])f.elements.name.value=lines[0].replace(/0\d{9}/,'').trim();if(lines[1])f.elements.address.value=lines[1];if(lines[2])f.elements.product.value=lines[2];f.dispatchEvent(new Event('input'))});$('#new-address').onchange=e=>{f.elements.region.innerHTML='<option value="">Chọn khu vực</option>'+ (e.target.checked?['Hà Nội · Phường Từ Liêm','TP. Hồ Chí Minh · Phường Tân Sơn Hòa','Gia Lai · Phường Bình Định']:['Hà Nội · Nam Từ Liêm · Mễ Trì','TP. Hồ Chí Minh · Tân Bình · Phường 13','Bình Định · An Nhơn · Bình Định']).map(s=>`<option>${s}</option>`).join('')};}
function renderOrders(){const list=(filtered||orders).filter(o=>tab==='Tất cả'||tab==='Chưa lấy hàng'&&o.status==='Chờ Lấy Hàng'||tab==='Đã hủy'&&o.status==='Đã hủy');$('#main').innerHTML=`<div class="title-row"><h1>Đơn hàng <span class="badge-blue">${orders.length}</span></h1><div class="actions"><button class="btn" id="export">▤ Xuất CSV</button><button class="btn" id="print">▣ In tem (K46)</button></div></div><div class="tabs">${['Tất cả','Chưa lấy hàng','Đã lấy hàng - Đang giao hàng','Hoãn giao hàng','Đã giao hàng','Đang chuyển hoàn','Đã trả hàng','Đã hủy'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t} (${t==='Tất cả'?orders.length:t==='Chưa lấy hàng'?orders.filter(o=>o.status==='Chờ Lấy Hàng').length:t==='Đã hủy'?orders.filter(o=>o.status==='Đã hủy').length:0})</button>`).join('')}</div><section class="card body"><h2>Bộ lọc đơn hàng</h2><form id="filters" class="filters"><div>${select('Trạng thái đơn hàng','status',['Chờ Lấy Hàng','Đã hủy'])}${field('Số Điện Thoại','phone','☎  Số Điện Thoại')}${field('Mã đơn riêng ⓘ','privateId','▥  Mã Đơn Riêng')}</div><div>${field('Mã tải đơn','batch','▥  Mã tải đơn')}${field('Mã Đơn Hàng','id','▦  Mã Đơn Hàng')}${field('Mã Đối Soát','reconcile','◧  Mã Đối Soát')}</div><div>${select('Thời gian','date',['7 ngày trước (07/09/2026 - 13/09/2026)','Hôm nay','30 ngày trước','Tất cả thời gian'])}<div class="filter-options"><div class="option-line"><span>Lấy hàng</span>${check('Đã lấy','picked')}${check('Chưa lấy','unpicked')}</div><div class="option-line"><span>Người trả phí</span>${check('Người gửi','sender')}${check('Người nhận','recipient')}</div><div class="option-line"><span>In đơn</span>${check('Chưa in','unprinted')}${check('Đã in','printed')}</div><div class="option-line"><span>Sắp xếp</span>${radio('sort','Mới nhất','new',true)}${radio('sort','Cũ nhất','old')}</div><div class="actions"><button type="reset" class="btn">↺ Đặt lại</button><button class="btn primary">⌕ Tìm kiếm</button></div></div></div></form></section><section class="card body" style="margin-top:24px"><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Chọn tất cả"></th><th>Mã Đơn Hàng</th><th>Khách Hàng</th><th>Thông Tin Đơn Hàng</th><th>Tiền Thu Khách</th><th>Trị Giá Hàng</th><th>Trạng Thái Đơn Hàng</th><th>Tác Vụ</th></tr></thead><tbody>${list.map(o=>`<tr><td><input type="checkbox" class="order-select" value="${esc(o.id)}" aria-label="Chọn đơn ${esc(o.id)}"></td><td><b>${esc(o.id)}</b><br><span class="hint">12/09/2026 • 11:26</span></td><td>♟ ${esc(o.name)}<br>☎ ${esc(o.phone)}<br>● ${esc(o.address)}</td><td>◆ ${esc(o.product)}<br>▣ ${esc(o.weight)} gr<br><i>${esc(o.note)}</i></td><td class="red">${money(o.cod)}</td><td class="green">${money(o.value)}</td><td><span class="status">${o.status}</span></td><td><div class="row-actions">${[['◉','Chi tiết','detail'],['➤','Gửi yêu cầu hỗ trợ','support'],['↻','Tạo lại','repeat'],['✎','Sửa đơn','edit'],['▣','In đơn','print'],['×','Hủy đơn','cancel']].map(([i,t,a])=>`<button title="${t}" data-action="${a}" data-id="${esc(o.id)}">${i}</button>`).join('')}</div></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">Không tìm thấy đơn hàng phù hợp</div>':''}</div><div class="pagination"><span>Đang hiển thị ${list.length?'1 - '+list.length:'0'} của ${list.length} tổng cộng</span><span>‹ &nbsp; <button>1</button> &nbsp; ›</span></div></section>${footer()}`;$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderOrders();bindCommon()});$('#filters').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));filtered=orders.filter(o=>(!d.status||o.status===d.status)&&['phone','privateId','id'].every(k=>!d[k]||String(o[k]||'').toLowerCase().includes(d[k].toLowerCase()))&&(!d.batch&&!d.reconcile)&&(!d.picked)&&(!d.printed||o.printed)&&(!d.unprinted||!o.printed)&&(!d.sender||o.payer!=='recipient')&&(!d.recipient||o.payer==='recipient'));if(d.sort==='old')filtered.reverse();renderOrders();bindCommon();toast('Đã áp dụng bộ lọc')};$('#filters').onreset=()=>{filtered=null;tab='Tất cả';setTimeout(()=>{renderOrders();bindCommon()},0)};$('#select-all').onchange=e=>$$('.order-select').forEach(x=>x.checked=e.target.checked);$('#export').onclick=()=>download('superplatform-orders.csv','\ufeffMã đơn,Tên người nhận,Số điện thoại,Sản phẩm,Thu hộ,Trạng thái\n'+list.map(o=>[o.id,o.name,o.phone,o.product,o.cod,o.status].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv');$('#print').onclick=()=>{const ids=$$('.order-select:checked').map(x=>x.value);if(!ids.length)return toast('Vui lòng chọn đơn cần in.');printOrders(orders.filter(o=>ids.includes(o.id)))};$$('[data-action]').forEach(b=>b.onclick=()=>orderAction(b.dataset.action,b.dataset.id));}
function modal(title,body,buttons='<button class="btn primary" data-close>Đóng</button>'){const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head">${title}</div><div class="modal-body">${body}</div><div class="modal-foot">${buttons}</div>`;$$('[data-close]',d).forEach(b=>b.onclick=()=>d.close());if(!d.open)d.showModal()}
function orderAction(a,id){const o=orders.find(x=>x.id===id);if(a==='support'){modal('Gửi Yêu Cầu Hỗ Trợ',`<form id="support-form"><label class="field"><span>Đơn hàng</span><div class="control" style="background:white;border-color:#528aff">${esc(o.phone)} - ${esc(o.name)}<br>${esc(o.id)}<br>${esc(o.address)}</div></label>${select('Danh mục','category',['Lấy Hàng','Giao Hàng','Trả Hàng','Đối Soát','Đơn Hàng'],true)}<label class="field"><span>Nội dung <b class="red">*</b></span><textarea name="content" placeholder="Nhập nội dung cần hỗ trợ" rows="4" required></textarea></label></form>`,'<button class="btn" data-close>Đóng</button><button class="btn primary" form="support-form">Gửi yêu cầu</button>');$('#support-form').onsubmit=e=>{e.preventDefault();tickets.push({...Object.fromEntries(new FormData(e.target)),order:id});$('#modal').close();toast('Đã lưu yêu cầu mẫu. Chưa gửi tới bộ phận hỗ trợ.')}}else if(a==='cancel'){modal('Hủy đơn hàng',`Bạn muốn hủy đơn <b>${esc(id)}</b>?`,'<button class="btn" data-close>Quay lại</button><button class="btn primary" id="confirm-cancel">Hủy đơn</button>');$('#confirm-cancel').onclick=()=>{o.status='Đã hủy';$('#modal').close();renderOrders();bindCommon();toast('Đã hủy đơn mẫu')}}else if(a==='print')printOrders([o]);else if(a==='repeat'||a==='edit'){location.hash='create';setTimeout(()=>{const f=$('#create-form');for(const k of ['name','phone','address','product','weight','value','cod','note'])f.elements[k].value=o[k]||'';f.dispatchEvent(new Event('input'));toast(a==='edit'?'Đã điền thông tin. Bản UI sẽ tạo một đơn mẫu mới khi lưu.':'Đã sao chép thông tin tạo đơn.')},0)}else modal('Chi tiết đơn hàng',`<b>${esc(o.id)}</b><p><span class="status">${o.status}</span></p><p>${esc(o.name)} · ${esc(o.phone)}<br>${esc(o.address)}</p><div class="step">${esc(o.product)} · ${esc(o.weight)} gr<br>Thu hộ: <b>${money(o.cod)}</b><br>Giá trị: ${money(o.value)}</div><p>${esc(o.note)}</p>`)}
function printOrders(items){items.forEach(o=>o.printed=true);modal('In tem đơn hàng',`<div id="print-content">${items.map(o=>`<section class="step"><h3>${esc(o.id)}</h3><p>${esc(o.name)} · ${esc(o.phone)}<br>${esc(o.address)}</p><b>${esc(o.product)} · ${esc(o.weight)} gr</b><p>Thu hộ: ${money(o.cod)}</p></section>`).join('')}</div>`,'<button class="btn" data-close>Đóng</button><button class="btn primary" id="do-print">In tem</button>');$('#do-print').onclick=()=>window.print()}
function help(){modal('Hướng Dẫn Sử Dụng',`<label class="choice red" style="justify-content:center;margin-bottom:22px"><input id="hide-help" type="checkbox" ${localStorage.getItem('hide-help')?'checked':''}>Ẩn hướng dẫn cho những lần tải trang sau</label><div class="step-title">Bước 1</div><div class="step pink">Nhập vào các thông tin cần thiết ở các trường bắt buộc như:<br><b>Tên Người Nhận, SĐT Người Nhận, Địa Chỉ Chi Tiết, Sản Phẩm, Khối Lượng</b> (gram), <b>Thu Hộ</b> (đồng), <b>Giá Trị</b> (đồng).<p>Tick/Chọn vào ô <b>Đổi Lấy Hàng Về</b> (nếu có nhu cầu) và ghi chú thêm vào ô <b>Ghi Chú</b>.</p><span class="green">Lưu ý: Các trường có dấu hoa thị [*] là các trường bắt buộc điền.</span></div><div class="step-title">Bước 2</div><div class="step">Chọn chính xác <b>Tỉnh/Thành Phố, Quận/Huyện/Thị Xã, Phường/Xã/Thị Trấn</b> theo địa chỉ người nhận.<p class="red">Vui lòng kiểm tra lại dữ liệu một lần nữa để đảm bảo thông tin chính xác.</p></div><div class="step-title">Bước 3</div><div class="step">Chọn <b>Kiểm Tra Dữ Liệu</b>, các dòng hợp lệ sẽ hiển thị với màu nền xanh.<p>Nhấn <b>Tạo Nhiều Đơn Hàng</b> để tạo đơn trong bản UI.</p></div>`);$('#modal').style.width='730px';$('#hide-help').onchange=e=>{if(e.target.checked)localStorage.setItem('hide-help','1');else localStorage.removeItem('hide-help')}}
function renderSheet(route){const two=route==='sheet2';const heads=['STT','Mã Đơn Của Shop','Tên Người Nhận [*]','SĐT Người Nhận [*]','Địa Chỉ Chi Tiết [*]','Tỉnh/Thành Phố [*]',...(!two?['Quận/Huyện/Thị Xã [*]']:[]),'Phường/Xã/Thị Trấn [*]','Hàng Hóa Cần Giao [*]','Khối Lượng [*]','Thu Hộ [*]','Giá Trị [*]','Ghi Chú'];$('#main').innerHTML=`<div class="title-row"><h1>Bảng tính ${two?'2':'3'} cấp</h1><button class="btn" data-help>▣ Hướng dẫn sử dụng</button></div><div class="sheet"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${Array.from({length:25},(_,i)=>`<tr data-row="${i}"><td>${i+1}</td>${heads.slice(1).map((h,j)=>`<td><input aria-label="Dòng ${i+1}, ${h}" data-col="${j}" value="${esc(sheetRows[i]?.[j]||'')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="sheet-footer"><a class="btn" href="#create">⌂ Về trang chủ</a><div class="actions"><button class="btn" id="validate-sheet">✓ Kiểm tra dữ liệu</button><button class="btn primary" id="create-many" disabled>▦ Tạo nhiều đơn</button></div></div><div class="sheet-settings"><div><div class="radios">Lưu nháp ${radio('draft-mode','Tự động','auto',true)}${radio('draft-mode','Thủ công','manual')}</div><p class="hint" id="draft-status">Lưu gần nhất: Chưa lưu trên thiết bị này</p><button class="btn" id="restore">↶ Khôi phục dữ liệu</button> <button class="btn" id="save-draft">▣ Lưu nháp</button></div>${pickupBlock()}<button class="btn" id="defaults">⚙ Cấu hình mặc định</button></div>${footer()}`;let valid=[];const read=()=>$$('.sheet tbody tr').map(tr=>$$('input',tr).map(x=>x.value));const save=()=>{sheetRows=read();localStorage.setItem(route+'-draft',JSON.stringify(sheetRows));$('#draft-status').textContent='Lưu gần nhất: '+new Date().toLocaleTimeString('vi-VN')};$('.sheet').oninput=()=>{$('#create-many').disabled=true;if($('[name=draft-mode]:checked').value==='auto')save()};$('.sheet').addEventListener('paste',e=>{if(e.target.tagName!=='INPUT')return;const data=e.clipboardData.getData('text');if(!data.includes('\t')&&!data.includes('\n'))return;e.preventDefault();const row=Number(e.target.closest('tr').dataset.row),col=Number(e.target.dataset.col);data.trimEnd().split(/\r?\n/).forEach((r,i)=>r.split('\t').forEach((v,j)=>{const el=$(`tr[data-row="${row+i}"] input[data-col="${col+j}"]`);if(el)el.value=v}));$('.sheet').dispatchEvent(new Event('input'))});$('#save-draft').onclick=()=>{save();toast('Đã lưu nháp trên thiết bị này')};$('#restore').onclick=()=>{sheetRows=JSON.parse(localStorage.getItem(route+'-draft')||'[]');renderSheet(route);bindCommon();toast('Đã khôi phục bản nháp trên thiết bị')};$('#validate-sheet').onclick=()=>{sheetRows=read();valid=[];sheetRows.forEach((r,i)=>{const used=r.some(Boolean);const product=two?6:7;const ok=used&&r.slice(1,product+4).every(x=>x.trim()!=='')&&/^0\d{9}$/.test(r[2])&&Number(r[product+1])>0&&Number(r[product+2])>=0&&Number(r[product+3])>=0;$(`tr[data-row="${i}"]`).className=used?(ok?'valid':'invalid'):'';if(ok)valid.push(r)});$('#create-many').disabled=!valid.length;toast(`${valid.length} dòng hợp lệ. Dòng đỏ cần kiểm tra thông tin bắt buộc và số điện thoại.`)};$('#create-many').onclick=()=>{const p=two?6:7;valid.forEach((r,i)=>orders.push({id:'SP'+Date.now()+i,privateId:r[0],name:r[1],phone:r[2],address:r.slice(3,p).join(', '),product:r[p],weight:r[p+1],cod:r[p+2],value:r[p+3],note:r[p+4],status:'Chờ Lấy Hàng'}));filtered=null;location.hash='orders';toast(`Đã tạo ${valid.length} đơn mẫu`)};$('#defaults').onclick=()=>{modal('Cấu hình mặc định',`<form id="defaults-form">${field('Khối lượng (gr)','weight','','750','number',true)}${field('Thu hộ (đ)','cod','','0','number',true)}</form>`,'<button class="btn" data-close>Đóng</button><button class="btn primary" form="defaults-form">Áp dụng cho dòng trống</button>');$('#defaults-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),p=two?6:7;$$('.sheet tbody tr').forEach(tr=>{for(const [c,v] of [[p+1,d.weight],[p+2,d.cod]]){const el=$(`input[data-col="${c}"]`,tr);if(!el.value)el.value=v}});$('#modal').close();$('#create-many').disabled=true;save()}};if(!localStorage.getItem('hide-help'))help()}
function renderOther(route){const title=menu.find(x=>x[2]===route)?.[1]||'Trang chủ';$('#main').innerHTML=`<h1>${title}</h1>${route==='requests'?card('Yêu cầu hỗ trợ','?',tickets.length?`<table><thead><tr><th>Đơn hàng</th><th>Danh mục</th><th>Nội dung</th><th>Trạng thái</th></tr></thead><tbody>${tickets.map(t=>`<tr><td>${esc(t.order)}</td><td>${esc(t.category)}</td><td>${esc(t.content)}</td><td>Bản mẫu</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Chưa có yêu cầu hỗ trợ. Bạn có thể tạo yêu cầu từ danh sách đơn hàng.</div>'):card(title,'▦','<div class="empty">Phần giao diện này sẽ được thiết kế ở bước tiếp theo.<p>Trước tiên, bạn có thể trải nghiệm các màn hình tạo và quản lý đơn hàng.</p><a href="#create" class="btn primary">Tạo đơn hàng</a> <a href="#orders" class="btn">Xem đơn hàng</a></div>')}${footer()}`}
function bindCommon(){$$('[data-help]').forEach(b=>b.onclick=help);$$('[data-pickup]').forEach(b=>b.onclick=()=>{modal('Thay đổi địa chỉ lấy hàng',`<form id="pickup-form">${field('Địa chỉ lấy hàng','pickup','',pickup,'text',true)}</form>`,'<button class="btn" data-close>Đóng</button><button class="btn primary" form="pickup-form">Lưu địa chỉ</button>');$('#pickup-form').onsubmit=e=>{e.preventDefault();pickup=new FormData(e.target).get('pickup');$('#modal').close();$$('.pickup').forEach(el=>{const wrap=document.createElement('div');wrap.innerHTML=pickupBlock();el.replaceWith(wrap.firstElementChild)});bindCommon();toast('Đã thay đổi địa chỉ lấy hàng trong bản UI')}})}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'read_demo_orders',title:'Xem đơn hàng mẫu',description:'Đọc danh sách đơn hàng hiện có trong bản UI SuperPlatform. Không kết nối hệ thống vận chuyển.',inputSchema:{type:'object',properties:{query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='query')||(input.query!==undefined&&typeof input.query!=='string'))throw new Error('query phải là chuỗi');const q=(input.query||'').toLowerCase();return {orders:orders.filter(o=>[o.id,o.name,o.phone].some(x=>x.toLowerCase().includes(q))).map(o=>({id:o.id,name:o.name,status:o.status,cod:Number(o.cod)}))}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
$('#modal').addEventListener('close',()=>$('#modal').style.width='');$('.menu').onclick=()=>document.body.classList.toggle('collapsed');$('#notifications').onclick=()=>modal('Thông báo','<div class="empty">Bạn chưa có thông báo mới.</div>');$('.account').onclick=()=>modal('Tài khoản','<b>S983262 - SUPERSHIP TEST</b><p>Raspberry Pi VN</p><p class="hint">Tài khoản mẫu để xem giao diện SuperPlatform.</p>');$('#global-search').onkeydown=e=>{if(e.key==='Enter'){const q=e.target.value.toLowerCase();filtered=orders.filter(o=>[o.id,o.phone,o.name].some(v=>v.toLowerCase().includes(q)));tab='Tất cả';if(location.hash==='#orders'){renderOrders();bindCommon()}else location.hash='orders'}};window.addEventListener('hashchange',render);render();
